import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent, VlTextComponent } from '@domg-wc/components/atom';
import {
    CompositeFormControl,
    parseFormData,
    VlFormLabelComponent,
    VlFormMessageComponent,
    VlInputFieldComponent,
} from '@domg-wc/components/form';
import { css, html } from 'lit';

// vl-composite-input is de voorbeeldcomponent van deze pagina, geen bibliotheekcomponent: neem hem over in je eigen
// project, onder je eigen tag. Het gedrag komt uit CompositeFormControl; de component voegt enkel de markup toe.
class CompositeInputComponent extends CompositeFormControl {
    static get styles() {
        return [
            css`
                fieldset {
                    border: 0;
                    padding: 0;
                    margin: 0;
                    display: flex;
                    gap: 0.5rem;
                    align-items: center;
                }

                .vl-u-visually-hidden {
                    position: absolute !important;
                    height: 1px;
                    width: 1px;
                    overflow: hidden;
                    clip: rect(1px, 1px, 1px, 1px);
                    margin: -1px;
                    padding: 0;
                    border: 0;
                    left: 0;
                    top: 0;
                }
            `,
        ];
    }

    render() {
        return html`
            <fieldset part="fieldset">
                <legend class="vl-u-visually-hidden">${this.label || 'Samengesteld invoerveld'}</legend>
                <slot @slotchange=${this.onSlotChange}></slot>
            </fieldset>
        `;
    }
}
customElements.define('vl-composite-input', CompositeInputComponent);

registerWebComponents([
    VlInputFieldComponent,
    VlFormLabelComponent,
    VlFormMessageComponent,
    VlButtonComponent,
    VlTextComponent,
]);

// Validator voor het samengestelde veld: krijgt per name van elk kind de waarde, als tekst. Geef een string terug om
// af te keuren, die tekst wordt de foutmelding; geef null terug als alles in orde is. Hij loopt pas wanneer alle
// velden ingevuld zijn: onvolledige invoer handelt required af.
const inBelgium = ({ 'coordinaten-lon': lon, 'coordinaten-lat': lat }) => {
    const longitude = parseFloat(lon);
    const latitude = parseFloat(lat);
    if (longitude < 2.5 || longitude > 6.5 || latitude < 49.5 || latitude > 51.6) {
        return `(lon=${lon}, lat=${lat}) ligt buiten België`;
    }
    return null;
};

// customValidator is een property, geen attribuut.
document.querySelector('#coordinaten').customValidator = inBelgium;

// Bij een gewone submit valideert de browser eerst, dus hier is de invoer zeker volledig. Lees je elders zelf
// new FormData(form) uit, controleer dan eerst form.checkValidity(): de composite houdt onvolledige invoer tegen met
// validatie, ze laat de waarden wel in de FormData staan.
const form = document.querySelector('#form');
const output = document.querySelector('#form-data');
form.addEventListener('submit', (event) => {
    event.preventDefault();
    output.textContent = JSON.stringify(parseFormData(form), null, 4);
    output.hidden = false;
});
form.addEventListener('reset', () => {
    output.textContent = '';
    output.hidden = true;
});

