const output = document.querySelector('#form-data');
form.addEventListener('submit', (event) => {
    event.preventDefault();
    output.textContent = JSON.stringify(parseFormData(form), null, 4);
    output.hidden = false;
});
form.addEventListener('reset', () => {
    output.textContent = '';
    output.hidden = true;
});

