const METHODS = [
    { value: 'email', label: 'E-mail' },
    { value: 'tel', label: 'Telefoon' },
];

const EMAIL = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
const PHONE = /^[\d\s/().+-]{6,}$/;

// Het eerste veld bepaalt welke regel op het tweede geldt: een e-mailadres of een telefoonnummer.
const valideerContact = ({ 'contact-method': method, 'contact-value': value }) => {
    if (!method || !value) return null;
    if (method === 'email') return EMAIL.test(value) ? null : `'${value}' is geen geldig e-mailadres.`;
    if (method === 'tel') return PHONE.test(value) ? null : `'${value}' is geen geldig telefoonnummer.`;
    return null;
};

// Het tweede veld per methode, met de attributen uit de demo.
const VELDEN = {
    email: { label: 'E-mailadres', type: 'email', placeholder: 'naam@voorbeeld.be' },
    tel: { label: 'Telefoonnummer', type: 'tel', placeholder: '+32 ...' },
};

const form = document.querySelector('#form');
const output = document.querySelector('#form-data');
const composite = document.querySelector('#contact');
const method = document.querySelector('#method');

// options en customValidator zijn properties, geen attributen.
method.options = METHODS;
composite.customValidator = valideerContact;

// Het tweede veld verschijnt pas na de keuze van een methode, en begint bij elke keuze leeg. Een veld dat later
// bijkomt of verdwijnt, neemt de composite vanzelf mee in de validatie.
const toonVeld = (keuze) => {
    composite.querySelector('#value')?.remove();
    const veld = VELDEN[keuze];
    if (!veld) return;
    const input = document.createElement('vl-input-field');
    input.setAttribute('id', 'value');
    input.setAttribute('name', 'contact-value');
    input.setAttribute('label', veld.label);
    input.setAttribute('type', veld.type);
    input.setAttribute('placeholder', veld.placeholder);
    composite.append(input);
};

method.addEventListener('vl-change', () => toonVeld(method.value));

form.addEventListener('submit', (event) => {
    event.preventDefault();
    output.textContent = JSON.stringify(parseFormData(form), null, 4);
    output.hidden = false;
});
form.addEventListener('reset', () => {
    toonVeld('');
    output.textContent = '';
    output.hidden = true;
});
